//! Canonical tenant persistence and transaction-scoped tenant context (#183).
//!
//! Tenant IDs are generated by Eye and must be obtained from a verified principal
//! (the API-client binding contract is implemented in #184). Never construct this
//! context from a request body, query parameter, or caller-controlled header.

use sqlx::{PgPool, Postgres, Row, Transaction};
use thiserror::Error;
use uuid::Uuid;

#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub struct TenantId(String);

impl TenantId {
    pub fn generate() -> Self {
        Self(format!("ten_{}", Uuid::new_v4().simple()))
    }

    pub fn parse(value: impl Into<String>) -> Result<Self, TenantStoreError> {
        let value = value.into();
        let valid = value.strip_prefix("ten_").is_some_and(|suffix| {
            suffix.len() == 32
                && suffix
                    .bytes()
                    .all(|byte| byte.is_ascii_digit() || (b'a'..=b'f').contains(&byte))
        });
        if !valid {
            return Err(TenantStoreError::InvalidInput);
        }
        Ok(Self(value))
    }

    pub fn as_str(&self) -> &str {
        &self.0
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Tenant {
    pub tenant_id: TenantId,
    pub owner_user_id: String,
    pub display_name: String,
    pub created_at_ms: i64,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Error)]
pub enum TenantStoreError {
    #[error("tenant input is invalid")]
    InvalidInput,
    #[error("tenant owner does not exist")]
    OwnerNotFound,
    #[error("tenant persistence is unavailable")]
    Unavailable,
}

impl From<sqlx::Error> for TenantStoreError {
    fn from(_: sqlx::Error) -> Self {
        Self::Unavailable
    }
}

pub async fn create_tenant(
    pool: &PgPool,
    owner_user_id: &str,
    display_name: &str,
    now_ms: i64,
) -> Result<Tenant, TenantStoreError> {
    let display_name = display_name.trim();
    if owner_user_id.is_empty()
        || owner_user_id.len() > 84
        || display_name.is_empty()
        || display_name.len() > 120
        || display_name.chars().any(char::is_control)
        || now_ms <= 0
    {
        return Err(TenantStoreError::InvalidInput);
    }

    let tenant_id = TenantId::generate();
    let mut tx = pool.begin().await?;

    let owner_exists: bool = sqlx::query_scalar(
        "SELECT EXISTS(SELECT 1 FROM eye_auth_users WHERE user_id = $1 AND is_active = TRUE)",
    )
    .bind(owner_user_id)
    .fetch_one(&mut *tx)
    .await?;
    if !owner_exists {
        tx.rollback().await?;
        return Err(TenantStoreError::OwnerNotFound);
    }

    sqlx::query(
        "INSERT INTO eye_tenants (tenant_id, owner_user_id, display_name, status, created_at_ms, updated_at_ms) \
         VALUES ($1, $2, $3, 'ACTIVE', $4, $4)",
    )
    .bind(tenant_id.as_str())
    .bind(owner_user_id)
    .bind(display_name)
    .bind(now_ms)
    .execute(&mut *tx)
    .await?;

    tx.commit().await?;

    Ok(Tenant {
        tenant_id,
        owner_user_id: owner_user_id.to_owned(),
        display_name: display_name.to_owned(),
        created_at_ms: now_ms,
    })
}

/// Starts a transaction with a tenant ID bound using PostgreSQL's transaction-local
/// setting. The value is cleared on commit or rollback, including when a pooled
/// connection is reused. The ID must come from a verified API-client principal or
/// another trusted server-side authorization decision.
pub async fn begin_tenant_transaction<'a>(
    pool: &'a PgPool,
    tenant_id: &TenantId,
) -> Result<Transaction<'a, Postgres>, sqlx::Error> {
    let mut tx = pool.begin().await?;
    bind_tenant_context(&mut tx, tenant_id).await?;
    Ok(tx)
}

/// Binds the trusted tenant to an existing transaction for subsequent RLS-protected
/// queries. Do not use session-level SET; the value must never survive pool reuse.
pub async fn bind_tenant_context(
    tx: &mut Transaction<'_, Postgres>,
    tenant_id: &TenantId,
) -> Result<(), sqlx::Error> {
    sqlx::query_scalar::<_, String>("SELECT set_config('eye.tenant_id', $1, TRUE)")
        .bind(tenant_id.as_str())
        .fetch_one(&mut **tx)
        .await?;
    Ok(())
}

/// Reads a tenant by ID without disclosing inactive/legacy rows to normal callers.
/// Authorization to access this tenant must already have been established by the caller.
pub async fn find_active_tenant(
    pool: &PgPool,
    tenant_id: &TenantId,
) -> Result<Option<Tenant>, TenantStoreError> {
    let row = sqlx::query(
        "SELECT tenant_id, owner_user_id, display_name, created_at_ms \
         FROM eye_tenants WHERE tenant_id = $1 AND status = 'ACTIVE'",
    )
    .bind(tenant_id.as_str())
    .fetch_optional(pool)
    .await?;

    let Some(row) = row else {
        return Ok(None);
    };

    let raw_id: String = row.try_get("tenant_id")?;
    let owner_user_id: String = row.try_get("owner_user_id")?;
    let display_name: String = row.try_get("display_name")?;
    let created_at_ms: i64 = row.try_get("created_at_ms")?;
    let tenant_id = TenantId::parse(raw_id).map_err(|_| TenantStoreError::Unavailable)?;

    Ok(Some(Tenant {
        tenant_id,
        owner_user_id,
        display_name,
        created_at_ms,
    }))
}
